const initial={lang:'EN',location:'Nepal',stage:'Exploring study',city:'Christchurch',level:'Not decided',interests:['Study','Jobs'],saved:[],checks:{},skills:{},budget:{Rent:240,Food:90,Transport:30,Phone:10,Internet:10,Electricity:25,Entertainment:30,'Study costs':15,Other:20,Income:0},onboarded:false};let state;try{state={...initial,...JSON.parse(localStorage.getItem('sajilo-prototype')||'{}')}}catch{state={...initial}}let route='',params=new URLSearchParams(),onstep=0,courseQuery='',courseCity='All cities',courseLevel='All levels',courseDuration='Any duration',courseIntake='Any intake',courseSubject='All subjects',courseProvider='All institutions',communityCategory='All',communityCity='Christchurch',mapMode=false,immFilter='All',budgetPeriod='Weekly',cvType='Skills-focused',compare=[],globalQ='',itemQ='',arrivalTab='Before Flight';
function persist(){localStorage.setItem('sajilo-prototype',JSON.stringify(state))}function t(en,np){return state.lang==='नेपाली'?np:en}function go(r){location.hash=r}function toast(s){const el=document.getElementById('toast');el.textContent=s;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2800)}function save(id,title,target){let found=state.saved.find(x=>x.id===id);state.saved=found?state.saved.filter(x=>x.id!==id):[...state.saved,{id,title,target}];persist();render(false);toast(found?'Removed from saved':'Saved to your journey')}function savedButton(id,title,target){return `<button class="icon-btn ${state.saved.some(x=>x.id===id)?'saved':''}" data-save="${esc(id)}" data-title="${esc(title)}" data-target="${esc(target)}" aria-label="${state.saved.some(x=>x.id===id)?'Unsave':'Save'} ${esc(title)}">${icon('save')}</button>`}function link(r,label,cls='btn',ic='arrow'){return `<a class="${cls}" href="#${r}">${label}${icon(ic)}</a>`}function external(url,label,cls='text-link'){return `<a href="${url}" target="_blank" rel="noopener noreferrer" class="${cls}">${label}${icon('external')}</a>`}function title(k,h,p,extra=''){return `<div class="page-head"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p>${p}</p></div>${extra}</div>`}function notice(text,green=false){return `<div class="notice ${green?'green':''}">${icon(green?'shield':'help')}<div>${text}</div></div>`}function section(h,body){return `<section class="card"><h2>${h}</h2>${body}</section>`}
const sources={inz:['Immigration New Zealand','https://www.immigration.govt.nz/'],nzqa:['NZQA','https://www2.nzqa.govt.nz/qualifications-and-standards/about-new-zealand-qualifications-credentials-framework/'],mpi:['Ministry for Primary Industries','https://www.mpi.govt.nz/bring-send-to-nz/bringing-and-posting-items-to-nz/check-if-you-can-bring-or-send-an-item-to-nz/'],customs:['NZ Customs','https://www.customs.govt.nz/'],tenancy:['Tenancy Services','https://www.tenancy.govt.nz/'],employment:['Employment New Zealand','https://www.employment.govt.nz/'],nzta:['NZ Transport Agency Waka Kotahi','https://www.nzta.govt.nz/'],nepal:['Embassy of Nepal, Canberra','https://au.nepalembassy.gov.np/'],careers:['Careers NZ','https://www.careers.govt.nz/job-hunting/cvs-and-cover-letters/'],study:['Study with New Zealand','https://www.studywithnewzealand.govt.nz/'],nztd:['New Zealand Traveller Declaration','https://www.travellerdeclaration.govt.nz/']};
function source(key,checked=false,effective='',url=''){const s=sources[key];return `<div class="source"><strong>${icon('shield')}${checked?'Verified information':'Official source · check current guidance'}</strong><div>${s[0]}</div><p>Last ${checked?'verified: 23 September 2026':'verified: not yet reviewed in this prototype'}</p>${effective?`<p>Effective: ${effective}</p>`:''}${external(url||s[1],'View official source')}</div>`}
const navigation=[['home','home','Home','गृह'],['explore','compass','Explore','खोज्नुहोस्'],['journey','journey','Journey','यात्रा'],['community','users','Community','समुदाय'],['profile','user','Profile','प्रोफाइल']];
function activeNav(){if(['home','welcome','onboarding'].includes(route))return 'home';if(['journey','predeparture','firstweek','saved'].includes(route))return 'journey';if(['community','organisation','events'].includes(route))return 'community';if(['profile','design'].includes(route))return 'profile';return 'explore'}
function shell(content){return `<aside class="sidebar"><a href="#home" class="brand"><span class="brand-mark">${icon('journey')}</span><span>sajilo<em> nz</em></span></a><nav class="nav">${navigation.map(([r,i,en,np])=>`<a href="#${r}" class="${activeNav()===r?'active':''}">${icon(i)}${t(en,np)}${r==='journey'?'<span class="count">'+Object.values(state.checks).filter(Boolean).length+'</span>':''}</a>`).join('')}<div class="nav-label">YOUR POCKET GUIDE</div><a href="#saved">${icon('save')}Saved resources <span class="count">${state.saved.length}</span></a><a href="#support">${icon('heart')}Help & wellbeing</a></nav><div class="side-bottom"><div class="help-box">${icon('shield')}<strong> A little help, a long way.</strong><p>Trusted sources. Clear next steps.<br>One journey at a time.</p><a href="#support">We’re here to help →</a></div><a class="profile-mini" href="#profile"><span class="avatar">S</span><span><strong>My student space</strong><br><span class="micro">${esc(state.city)} · ${esc(state.location)}</span></span>${icon('chevron')}</a></div></aside><header class="topbar"><div class="mobile-brand"><a href="#home" class="brand"><span class="brand-mark">${icon('journey')}</span><span>sajilo<em> nz</em></span></a></div><a class="top-search" href="#search">${icon('search')}Search anything about life in New Zealand <kbd>⌘ K</kbd></a><div class="top-actions"><span class="state-banner">Interactive prototype</span><button class="lang" data-action="language" aria-label="Switch language"><strong>${state.lang==='EN'?'EN':'नेपाली'}</strong> <span> | ${state.lang==='EN'?'नेपाली':'EN'}</span></button><a href="#support" class="help-shortcut" aria-label="Emergency help and support">${icon('heart')}<span>Help</span></a><a href="#immigration" class="icon-btn" aria-label="Important updates">${icon('bell')}</a><a href="#profile" class="avatar" aria-label="Profile">S</a></div></header><main class="main" id="main">${content}<div class="footer-note">Made for your next chapter. &nbsp; नेपालदेखि न्युजिल्याण्डसम्म ♡<br>Prototype · Sample content is labelled · Your progress stays on this device</div></main><nav class="bottom-nav" aria-label="Main navigation">${navigation.map(([r,i,en,np])=>`<a href="#${r}" class="${activeNav()===r?'active':''}">${icon(i)}${t(en,np)}</a>`).join('')}</nav>`}
const courses=[{id:'ara',name:'Bachelor of Information and Communication Technologies',provider:'Ara Institute of Canterbury',city:'Christchurch',level:7,duration:'3 years',intake:'February',type:'Bachelor’s',url:'https://www.ara.ac.nz/',subject:'Computing'},{id:'uc',name:'Bachelor of Engineering with Honours',provider:'University of Canterbury',city:'Christchurch',level:8,duration:'4 years',intake:'February',type:'Bachelor’s Honours',url:'https://www.canterbury.ac.nz/',subject:'Engineering'},{id:'aut',name:'Master of Software Development',provider:'Sample institution',city:'Auckland',level:9,duration:'18 months',intake:'July',type:'Master’s',url:'https://www.studywithnewzealand.govt.nz/',subject:'Computing'},{id:'wgtn',name:'Graduate Diploma in Information Technology',provider:'Sample institution',city:'Wellington',level:7,duration:'1 year',intake:'July',type:'Graduate Diploma',url:'https://www.studywithnewzealand.govt.nz/',subject:'Computing'}];
const pre={Documents:['Passport','Visa/eVisa','Offer of place','Academic documents','Insurance','Accommodation confirmation','Flight itinerary','Emergency contacts'],Packing:['Clothing','Laptop','Chargers','Medication','Important document copies','Personal items'],Money:['NZD','Bank cards','Emergency money','First-month budget'],'Before leaving Nepal':['Passport validity','Check visa conditions','Confirm accommodation','Airport transport','Baggage allowance','Transit requirements','Important contacts','Review biosecurity rules','Traveller declaration']};const first={'Your first week':['Get a SIM','Open a bank account','Apply for an IRD number','Register with a healthcare provider','Set up transport','Confirm accommodation','Learn emergency numbers','Get your student ID','Explore campus','Join student/community groups']};const studyTasks=['Find courses that fit your goals','Understand the NZ education system','Explore student visa information','Plan your living costs'];const taskDest={'Find courses that fit your goals':'courses','Understand the NZ education system':'education','Explore student visa information':'visa','Plan your living costs':'budget','First-month budget':'budget','Review biosecurity rules':'bring','Traveller declaration':'arrival','Airport transport':'arrival','Get a SIM':'guide?topic=Get%20a%20SIM','Open a bank account':'guide?topic=Open%20a%20bank%20account','Apply for an IRD number':'guide?topic=Apply%20for%20an%20IRD%20number','Learn emergency numbers':'support','Join student/community groups':'community'};
function checklistData(){return state.stage==='First weeks in NZ'?first:state.stage==='Preparing to travel'?pre:['Studying','Looking for work','Near graduation'].includes(state.stage)?{'Your next chapter':['Prepare your NZ CV','Practise your interview','Build your skills roadmap','Connect with your community']}:{'Your study plan':studyTasks}};Object.assign(taskDest,{'Prepare your NZ CV':'cv','Practise your interview':'interview','Build your skills roadmap':'skills','Connect with your community':'community'});function checkTask(item,group,desc=''){const id=group+':'+item;return `<div class="task ${state.checks[id]?'done':''}"><input type="checkbox" aria-label="Complete ${esc(item)}" data-check="${esc(id)}" ${state.checks[id]?'checked':''}><div class="task-content"><a class="task-title" href="#${taskDest[item]||('guide?topic='+encodeURIComponent(item))}">${esc(item)}</a>${desc?`<p>${desc}</p>`:''}<div class="task-meta"><a href="#${taskDest[item]||('guide?topic='+encodeURIComponent(item))}">Open guide →</a></div></div>${savedButton(id,item,taskDest[item]||'predeparture')}</div>`}
function home(){const data=checklistData(),all=Object.entries(data).flatMap(([g,ls])=>ls.map(n=>({g,n}))),done=all.filter(x=>state.checks[x.g+':'+x.n]).length;const stageName=state.stage==='Preparing to travel'?'Preparing for NZ':state.stage==='First weeks in NZ'?'Finding your feet':['Studying','Looking for work','Near graduation'].includes(state.stage)?'Your next opportunity':'Your study adventure';return title(t('YOUR NEXT CHAPTER','तपाईंको नयाँ अध्याय'),t('Namaste, welcome home 👋','नमस्ते, स्वागत छ 👋'),t(`A little closer to your New Zealand dream. Let’s take the next step.`,`न्युजिल्याण्डको यात्रामा एक कदम अगाडि बढौँ।`),`<a class="pill" href="#profile">${icon('pin')}${esc(state.city)}${icon('chevron')}</a>`)+`<div class="dashboard-grid"><div class="stack"><section class="journey-hero"><div class="hero-flex"><div><div class="eyebrow">${t('YOUR JOURNEY','तपाईंको यात्रा')}</div><h2>${t(stageName,state.stage==='Preparing to travel'?'न्युजिल्याण्ड जाने तयारी':'तपाईंको अध्ययन यात्रा')}</h2><p>${t('Big plans. Small, achievable steps.','ठूला योजना। साना, पूरा गर्न सकिने कदमहरू।')}</p><span class="pill">${icon('cap')}${esc(state.stage)}</span></div><div class="ring" style="--pct:${done/all.length*100}%"><div><strong>${done}<span style="font-size:14px;font-weight:400"> / ${all.length}</span></strong><small>steps complete</small></div></div></div><div class="hero-bottom"><span>${icon('spark').replace('<svg','<svg style="width:13px;height:13px;vertical-align:middle"')} A new beginning, at your own pace</span>${link('journey',t('View my journey','मेरो यात्रा'),'text-link')}</div></section><section class="card"><div class="section-head"><h2>${t('Your next steps','अब के गर्ने?')}</h2><span>Made for your stage</span></div>${all.filter(x=>!state.checks[x.g+':'+x.n]).slice(0,3).map((x,i)=>checkTask(x.n,x.g,['Start here. Build a shortlist that feels right for you.','A few useful things to know before your next step.','Clear guidance, directly from the official source.'][i])).join('')||notice('All caught up! Choose your next journey stage in your profile.',true)}<div style="margin-top:14px">${link('journey','See all steps','text-link')}</div></section><section><div class="section-head"><h2>${t('A few handy tools','उपयोगी उपकरणहरू')}</h2></div><div class="tool-grid">${[['courses','cap','Course finder',''],['budget','wallet','Budget planner','peach'],['bring','plane','Can I bring it?','blue'],['skills','code','Skills roadmap','yellow']].map(([r,i,n,c])=>`<a href="#${r}" class="tool"><span class="icon-tile ${c}">${icon(i)}</span>${n}</a>`).join('')}</div></section><section class="card"><div class="section-head"><h2>Keep your favourites close</h2>${link('saved','View saved','text-link')}</div>${state.saved.length?state.saved.slice(0,2).map(x=>`<a class="row-link" href="#${x.target}"><span>${icon('save')}${esc(x.title)}</span>${icon('chevron')}</a>`).join(''):`<p style="font-size:14px;margin:0">Found something useful? Tap the bookmark to keep it here for later.</p>`}</section></div><aside class="stack"><section class="card update-card"><div class="section-head"><span class="eyebrow" style="margin:0">GOOD TO KNOW</span>${icon('bell')}</div><span class="pill amber">Upcoming change · 16 Nov 2026</span><h3>New post-study work visa options announced</h3><p>Planning beyond graduation? Check what’s changing at the official source.</p>${link('update','Understand the update','text-link')}<div class="source-mini">${icon('shield')}Immigration New Zealand · Checked 23 Sep</div></section><section class="card"><div class="section-head"><h2>Your future neighbourhood</h2></div><a href="#city?name=${encodeURIComponent(state.city==='Not decided'?'Christchurch':state.city)}"><div class="city-graphic"><strong>${state.city==='Christchurch'?'CHC':'NZ'}</strong><span class="pill">${icon('pin')}${esc(state.city)}</span></div><h3>Find your place in ${esc(state.city)}</h3></a><p style="font-size:13px">Get to know your city, your campus, and your community.</p>${link('city?name='+encodeURIComponent(state.city),'Explore your city','text-link')}</section><section class="card"><div class="section-head"><h2>A little closer to home</h2></div><div class="event-row"><div class="event-date"><span>OCT</span><strong>17</strong></div><div><h3>Dashain Celebration</h3><p>Christchurch · Community gathering</p><span class="pill gray" style="margin-top:8px">Sample event</span></div></div><div style="margin-top:15px">${link('events','Discover community','text-link')}</div></section></aside></div>`}
function welcome(){return `<div class="welcome"><div class="welcome-left"><a href="#home" class="brand"><span class="brand-mark">${icon('journey')}</span><span>sajilo nz</span></a><div><div class="eyebrow" style="color:#c7d9c7">नेपालदेखि न्युजिल्याण्डसम्म</div><h1>Your next chapter.<br>A little easier.</h1><p>Your student journey from Nepal to New Zealand.</p></div><span class="micro" style="color:#d5e3d3">Study. Settle. Belong. Grow.</span></div><div class="welcome-right"><span class="pill" style="align-self:flex-start;margin-bottom:20px">Your trusted pocket companion</span><h2>Namaste. Let’s find<br>your next step.</h2><p>From your first questions in Nepal to your first job in New Zealand.</p><div class="welcome-points"><span>${icon('journey')}A journey that moves with you</span><span>${icon('shield')}Official sources, in plain language</span><span>${icon('users')}A community that feels like home</span></div>${link('onboarding','Make it yours')}<div style="text-align:center;margin-top:15px">${link('home','Explore first','text-link')}</div><p class="micro" style="margin:15px 0 0;text-align:center">No account needed. About a minute to set up.</p></div></div>`}
const onboarding=[['Preferred language','Make yourself at home.','lang',['EN','नेपाली']],['Where are you now?','We’ll meet you where you are.','location',['Nepal','Travelling soon','Recently arrived','Living in New Zealand']],['What stage are you in?','There’s no rush. You can change this anytime.','stage',['Exploring study','Applying','Visa preparation','Preparing to travel','First weeks in NZ','Studying','Looking for work','Near graduation']],['Which city is on your mind?','Optional · local information that’s useful to you.','city',['Auckland','Christchurch','Wellington','Hamilton','Dunedin','Other','Not decided']],['What would you like to study?','Optional · choose a qualification level.','level',['Certificate','Diploma','Bachelor’s','Graduate Diploma','Postgraduate Diploma','Master’s','PhD','Not decided']],['What matters most to you?','Optional · pick as many as you like.','interests',['Study','Immigration updates','Jobs','Money','Housing','Community','Travel','Skills']]];
function onboard(){let [h,p,key,opts]=onboarding[onstep];return `<section class="onboard">${link('welcome','Back to welcome','back','back')}<div class="progress-label"><span>LET’S MAKE THIS YOURS</span><span>${onstep+1} of 6</span></div><progress value="${onstep+1}" max="6"></progress><div style="margin-top:32px">${title('YOUR JOURNEY STARTS HERE',t(h,onstep===0?'आफ्नो भाषा छान्नुहोस्':h),p)}</div><div class="option-grid">${opts.map(o=>`<button class="option ${(Array.isArray(state[key])?state[key].includes(o):state[key]===o)?'active':''}" data-option="${esc(o)}" aria-pressed="${Array.isArray(state[key])?state[key].includes(o):state[key]===o}">${o==='EN'?'English':o==='Nepal'?'In Nepal':esc(o)}${(Array.isArray(state[key])?state[key].includes(o):state[key]===o)?icon('check'):''}</button>`).join('')}</div><div class="onboard-actions"><button class="text-link" data-action="onback">${onstep?'← Back':''}</button>${onstep>=3?'<button class="text-link" data-action="onskip">Skip for now</button>':''}<button class="btn" data-action="onnext">${onstep===5?'Show my journey':'Continue'}${icon('arrow')}</button></div><p class="micro" style="margin-top:30px;text-align:center">Only saved on this device. You can edit this in Profile.</p></section>`}
const categories=[['courses','cap','Study & courses','Find your course, campus, and direction.'],['immigration','shield','Immigration','Understand what to check, from official sources.'],['predeparture','plane','Prepare to travel','Documents, packing, money, and peace of mind.'],['firstweek','journey','Arrive & settle','Small steps for your first weeks in NZ.'],['housing','home','Housing & flatting','Find a place and understand your responsibilities.'],['budget','wallet','Money & budgeting','Plan for everyday life and unexpected costs.'],['jobs','briefcase','Work & careers','Build your confidence and your job toolkit.'],['community','users','Community','Find familiar faces and new connections.'],['consular','globe','Nepal services','Passport, documents, and official contacts.'],['travel','car','Travel & transport','Get around your new home.'],['support','heart','Student support','Help with study, wellbeing, and everyday life.'],['education','cap','Education system','Make sense of qualifications and levels.']];function categoryCards(list){return `<div class="grid">${list.map(([r,i,h,p])=>`<a href="#${r}" class="card category"><span class="icon-tile">${icon(i)}</span><h3>${h}</h3><p>${p}</p><span class="text-link">Explore ${icon('arrow')}</span></a>`).join('')}</div>`}
function explore(){return title('EXPLORE',t('A new country. A world of possibilities.','नयाँ देश। नयाँ सम्भावनाहरू।'),'Everything you need, in one friendly place.')+`<a href="#search" class="searchbox">${icon('search')}<span style="color:var(--muted)">What would you like to know?</span></a>`+categoryCards(categories)+`<div class="section-head" style="margin-top:32px"><h2>Get to know Aotearoa</h2></div><div class="grid">${['About New Zealand','Culture & Māori culture','Weather & climate','Healthcare','Laws & everyday rules','Student life'].map(n=>`<a class="row-link" href="#guide?topic=${encodeURIComponent(n)}"><span>${icon('book')}${n}</span>${icon('chevron')}</a>`).join('')}</div><div class="section-head" style="margin-top:32px"><h2>Find your city</h2></div><div class="filters">${['Auckland','Christchurch','Wellington','Hamilton','Dunedin'].map(n=>link('city?name='+n,n,'chip','pin')).join('')}</div>`}
function city(){const name=params.get('name')||state.city;return title('EXPLORE / CITIES',esc(name),name==='Christchurch'?'Ōtautahi · A fresh start between the hills and the sea.':'Find your campus, community, and everyday essentials.')+`<div class="two-col"><div class="stack">${section('Make yourself at home',`<p>${name==='Christchurch'?'A city with a creative centre, green spaces, and easy access to Canterbury’s outdoors. Start with your campus and explore one neighbourhood at a time.':'Explore neighbourhoods near your institution and check transport connections before choosing a place to live.'}</p><div class="inline-actions">${link('courses','Explore institutions & courses')}${link('community','Meet your community','btn secondary')}</div>`)}${section('Your city essentials',`<div class="rows">${[['budget','Approximate living costs'],['travel','Public transport'],['housing','Housing & neighbourhoods'],['jobs','Job-market links'],['support','Healthcare & student support'],['events','Student lifestyle & things to do']].map(([r,n])=>`<a class="row-link" href="#${r}"><span>${n}</span>${icon('chevron')}</a>`).join('')}</div>`)}${section('Weather & everyday life','<p>Check the local forecast, bring layers, and plan for changing weather. Ask your institution about orientation, campus clubs, and student discounts.</p>'+external('https://www.metservice.com/','Check the weather'))}</div><aside class="stack">${section('Plan a realistic week',`<span class="pill amber">Illustrative budget · not a city estimate</span><div class="big-number" style="margin-top:15px">$470</div><p>NZD per week in our editable example, excluding tuition and one-off arrival costs.</p>${link('budget','Make your own budget')}`)}${source('study')}</aside></div>`}
function education(){const levels={10:'Doctoral Degree',9:'Master’s Degree',8:'Bachelor Honours Degree · Postgraduate Certificate · Postgraduate Diploma',7:'Bachelor’s Degree · Graduate Certificate · Graduate Diploma · Diploma',6:'Certificate · Diploma',5:'Certificate · Diploma',4:'Certificate',3:'Certificate',2:'Certificate',1:'Certificate'};return title('STUDY / EDUCATION SYSTEM','Find your place on the framework','NZQCF · 10 levels, different kinds of learning.')+`<div class="two-col"><section class="card">${Object.entries(levels).reverse().map(([n,l])=>`<div class="level"><span class="level-number">${n}</span><div><h3>${l}</h3><p>NZQCF level ${n}</p></div></div>`).join('')}</section><aside class="stack">${section('A level is a guide',`<p>Levels describe the complexity of learning. Different qualifications can share a level. A higher level is not automatically the best fit for your goals.</p><p>Check admission requirements, subject, learning outcomes, and provider recognition for each course.</p>${link('courses','Find your course')}`)}${source('nzqa',true)}</aside></div>`}
function courseCard(c){return `<article class="card course"><div class="section-head"><span class="pill gray">Illustrative programme data</span>${savedButton('course:'+c.id,c.name,'course?id='+c.id)}</div><h3>${c.name}</h3><p>${c.provider}<br>${icon('pin').replace('<svg','<svg style="width:14px;height:14px;vertical-align:middle"')} ${c.city}</p><div class="course-meta"><span class="pill">Level ${c.level}</span><span class="pill gray">${c.duration}</span><span class="pill gray">${c.intake} intake</span></div><p class="micro">International entry: verify with provider<br><strong>Tuition: verify latest tuition with provider</strong></p><div class="course-actions">${link('course?id='+c.id,'View programme','btn small')}<button class="btn secondary small" data-compare="${c.id}">${compare.includes(c.id)?'✓ Comparing':'Compare'}</button></div></article>`}
function coursesPage(){let results=courses.filter(c=>(!courseQuery||[c.name,c.provider,c.subject,'software development engineering'].join(' ').toLowerCase().includes(courseQuery.toLowerCase()))&&(courseCity==='All cities'||c.city===courseCity)&&(courseLevel==='All levels'||String(c.level)===courseLevel)&&(courseDuration==='Any duration'||c.duration===courseDuration)&&(courseIntake==='Any intake'||c.intake===courseIntake)&&(courseSubject==='All subjects'||c.subject===courseSubject)&&(courseProvider==='All institutions'||c.provider===courseProvider));function sel(id,values,v){return `<select id="${id}" aria-label="${id.replace('filter-','')}">${values.map(o=>`<option ${o===v?'selected':''}>${o}</option>`).join('')}</select>`}return title('STUDY / COURSE FINDER','Your future starts with a good fit.','Explore courses, compare your options, and keep a shortlist.',link('compare',`Compare (${compare.length})`,'btn secondary'))+`<div class="searchbox">${icon('search')}<input id="course-query" placeholder="Search courses, careers or institutions" value="${esc(courseQuery)}" aria-label="Search courses"></div><div class="filters">${sel('filter-city',['All cities','Christchurch','Auckland','Wellington','Hamilton','Dunedin'],courseCity)}${sel('filter-level',['All levels','7','8','9'],courseLevel)}${sel('filter-subject',['All subjects','Computing','Engineering'],courseSubject)}${sel('filter-provider',['All institutions',...new Set(courses.map(c=>c.provider))],courseProvider)}${sel('filter-duration',['Any duration','1 year','18 months','3 years','4 years'],courseDuration)}${sel('filter-intake',['Any intake','February','July'],courseIntake)}</div><details><summary>Tuition & international entry</summary><p>Tuition ranges and international eligibility are not available in this sample dataset. Check the provider before comparing fees or entry requirements.</p></details><div class="section-head"><span>${results.length} sample programmes</span><button class="text-link" data-action="clearfilters">Reset filters</button></div>${results.length?`<div class="grid two">${results.map(courseCard).join('')}</div>`:empty('No courses match yet','Try a broader subject or clear the filters.','courses','Browse all courses')}<div style="margin-top:20px">${notice('Programme titles, durations, and intakes demonstrate the design. They are not a verified current course catalogue.')}</div>`}
function courseDetail(){let c=courses.find(x=>x.id===params.get('id'))||courses[0];return link('courses','Back to courses','back','back')+title('STUDY / PROGRAMME',c.name,c.provider, savedButton('course:'+c.id,c.name,'course?id='+c.id))+notice('Sample programme details. Verify the exact programme, international entry, duration, and intake directly with the institution.')+`<div class="two-col"><div class="stack">${section('A closer look',`<div class="stat-grid"><div class="stat"><strong>${c.level}</strong><span>NZQCF level · sample</span></div><div class="stat"><strong>${c.duration}</strong><span>Duration · sample</span></div><div class="stat"><strong>${c.city}</strong><span>Campus city</span></div></div><p>Explore programming, software design, databases, and practical projects. Use the official programme page to check the actual curriculum and learning outcomes.</p>${link('institution?id='+c.id,'Meet the institution','btn secondary')}`)}${section('Before you apply',`<div class="rows">${['Check academic and English entry requirements','Verify fees, scholarships, and payment dates','Confirm the next intake and application deadline','Ask about international student support'].map(n=>`<div class="row-link"><span>${icon('check')}${n}</span></div>`).join('')}</div>`)}</div><aside class="stack">${section('Keep your options open',`<p><strong>Tuition</strong><br>Verify latest tuition with provider.</p><p><strong>International students</strong><br>Confirm current entry with the provider.</p><div class="inline-actions">${external(c.url,'Official provider website','btn')}<button class="btn secondary" data-compare="${c.id}">${compare.includes(c.id)?'✓ Comparing':'Add to comparison'}</button></div>`)}${section('What comes next?',link('education','Understand NZ qualifications','text-link')+'<br>'+link('visa','Explore student visa information','text-link'))}</aside></div>`}
function institution(){let c=courses.find(x=>x.id===params.get('id'))||courses[0];return title('STUDY / INSTITUTION',c.provider,c.city,savedButton('institution:'+c.id,c.provider,'institution?id='+c.id))+notice('Provider overview is illustrative. Recognition and current offerings must be checked.')+`<div class="two-col"><div class="stack">${section('Campus & student experience',`<p>Explore campus facilities, course delivery, international support, and orientation through the provider’s website.</p>${external(c.url,'Visit institution website','btn')}`)}${section('Questions worth asking',`<div class="rows">${['International student information','Learning and wellbeing support','Accommodation links','Campus locations & accessibility','Available courses and intakes'].map(n=>`<div class="row-link"><span>${n}</span>${external(c.url,'Provider')}</div>`).join('')}</div>`)}${courseCard(c)}</div><aside>${section('Provider status',`<p>Check the official provider record and the Code signatory information with NZQA before making a decision.</p>${source('nzqa')}`)}</aside></div>`}
function comparePage(){let cs=courses.filter(c=>compare.includes(c.id));return title('STUDY / COMPARE','A clearer view of your options','Choose up to three programmes to compare.')+(cs.length?`<div class="table-wrap"><table><thead><tr><th>Programme</th>${cs.map(c=>`<th>${c.name}<br><button class="text-link" data-compare="${c.id}">Remove</button></th>`).join('')}</tr></thead><tbody>${[['Institution','provider'],['City','city'],['Level','level'],['Duration · sample','duration'],['Intake · sample','intake']].map(([n,k])=>`<tr><th>${n}</th>${cs.map(c=>`<td>${c[k]}</td>`).join('')}</tr>`).join('')}<tr><th>Tuition / international entry</th>${cs.map(c=>'<td>Verify with provider</td>').join('')}</tr><tr><th>Next step</th>${cs.map(c=>`<td>${link('course?id='+c.id,'View programme','btn small')}</td>`).join('')}</tr></tbody></table></div><div style="margin-top:20px">${link('courses','Add another course','btn secondary')}</div>`:empty('Your comparison starts here','Tap Compare on the courses you’re interested in.','courses','Find courses'))}
function immigration(){const cards=[['visa','cap','Student visas','Understand the application and where to check.','Student'],['visa?topic=Working while studying','briefcase','Working while studying','Check the conditions on your own visa.','Work'],['visa?topic=Visa conditions','shield','Visa conditions','Know what your visa allows and requires.','Student'],['update','journey','Post-study work information','Read current and upcoming official guidance.','Post-study'],['visa?topic=Partners and family','users','Partners and family','Find official information for your family.','Family'],['visa?topic=Residence information','home','Residence information','Explore official information, without eligibility predictions.','Residence'],['visa?topic=Licensed Immigration Advisers','shield','Licensed Immigration Advisers','Find a licensed adviser for individual advice.','All']].filter(x=>immFilter==='All'||x[4]===immFilter);return title('IMMIGRATION','Clear information. Trusted sources.','Understand what to check, and where to go next.')+notice('General information only. For personal immigration advice, contact Immigration New Zealand or a Licensed Immigration Adviser.')+`<div class="filters">${['All','Student','Work','Post-study','Family','Residence'].map(n=>`<button class="chip ${immFilter===n?'active':''}" data-imm="${n}">${n}</button>`).join('')}</div>`+`<div class="grid">${cards.map(([r,i,h,p])=>`<article class="card category"><span class="icon-tile">${icon(i)}</span><h3>${h}</h3><p>${p}</p>${link(r,'Open guide','text-link')}<div class="micro">Official source: Immigration New Zealand<br>Last verified: needs review</div>${external(sources.inz[1],'Read official source')}</article>`).join('')}</div>`+`<div class="section-head" style="margin-top:30px"><h2>Official updates timeline</h2><span>Checked 23 September 2026</span></div><article class="card"><span class="pill amber">Upcoming change · 16 November 2026</span><h3 style="margin-top:15px">New and updated post-study work visa options</h3><p>Immigration New Zealand has announced changes. Read the full criteria and effective dates directly.</p>${link('update','Read the update','text-link')}${source('inz',true,'16 November 2026',updateUrl)}</article>`}
const updateUrl='https://www.immigration.govt.nz/about-us/news-centre/new-and-updated-post-study-work-visa-options/';function update(){return link('immigration','Back to immigration','back','back')+title('IMMIGRATION / UPDATE','Planning beyond graduation?','New and updated post-study work visa options',`<span class="pill amber">Upcoming change</span>`)+`<div class="two-col"><section class="card"><span class="pill amber">Effective 16 November 2026</span><h2 style="margin-top:22px">What’s changing</h2><p>Immigration New Zealand has announced new and updated options for graduates, including a new Short-term Graduate Work Visa and expanded Post Study Work Visa eligibility.</p><p>Requirements differ by qualification and circumstances. This overview does not determine whether you qualify.</p><h3>Your next step</h3><p>Read the announcement, check the current rules, and seek licensed advice if you need help applying them to your situation.</p>${external(updateUrl,'Read the full official update','btn')}${source('inz',true,'16 November 2026',updateUrl)}</section><aside>${notice('General information only. For personal immigration advice, contact Immigration New Zealand or a Licensed Immigration Adviser.')}${savedButton('update','Post-study work update','update')}${link('visa?topic=Licensed Immigration Advisers','Find licensed advice','text-link')}</aside></div>`}
function visa(){const topic=params.get('topic')||'Student visas';return title('IMMIGRATION / OFFICIAL GUIDANCE',esc(topic),'A starting point for questions to check with the official source.')+notice('General information only. For personal immigration advice, contact Immigration New Zealand or a Licensed Immigration Adviser.')+`<div class="two-col"><section class="card"><h2>Start with the official guidance</h2><p>Requirements depend on the visa and your circumstances. Check current conditions, required evidence, application processes, fees, and processing information with Immigration New Zealand.</p><div class="rows">${['Read the current official requirements','Keep copies of your supporting documents','Check the conditions written on your eVisa','Get licensed help for personal questions'].map(n=>`<div class="row-link"><span>${icon('check')}${n}</span></div>`).join('')}</div>${source('inz')}${topic.includes('Adviser')?external('https://www.iaa.govt.nz/','Immigration Advisers Authority register','btn'):''}</section><aside>${section('Prepare one step at a time',`<p>Keep a practical travel checklist ready for when you need it.</p><button class="btn" data-action="addcheck">Add pre-departure checklist ${icon('arrow')}</button><div style="margin-top:15px">${savedButton('visa:'+topic,topic,'visa?topic='+encodeURIComponent(topic))}</div>`)}</aside></div>`}
function checklist(kind){const groups=kind==='predeparture'?pre:first,all=Object.entries(groups).flatMap(([g,a])=>a.map(n=>g+':'+n)),n=all.filter(i=>state.checks[i]).length;return title(kind==='predeparture'?'JOURNEY / BEFORE YOU FLY':'JOURNEY / SETTLE IN',kind==='predeparture'?'A little preparation. A calmer arrival.':'Your first week, one step at a time.',kind==='predeparture'?'Pack your essentials, prepare your documents, and feel ready.':'There’s a lot that’s new. Start with what matters today.')+`<section class="card" style="margin-bottom:24px"><div class="section-head"><h2>${n} of ${all.length} completed</h2><span>${Math.round(n/all.length*100)}%</span></div><progress value="${n}" max="${all.length}"></progress></section><div class="grid two">${Object.entries(groups).map(([g,items])=>`<section class="card"><h2>${g}</h2>${items.map(i=>checkTask(i,g)).join('')}</section>`).join('')}</div><div class="inline-actions" style="margin-top:24px">${link('bring','Check what you can bring','btn secondary')}${link(kind==='predeparture'?'arrival':'budget',kind==='predeparture'?'Follow the arrival guide':'Plan your budget')}</div>${kind==='firstweek'?source('study'):source('nztd')}`}
function bring(){return title('PRE-DEPARTURE / BIOSECURITY','Can I bring it to NZ?','Achar, spices, medicine? Check before you pack.')+notice('When in doubt, declare it. A declaration is not permission to bring an item in. Border officers make the final decision.')+`<div class="searchbox">${icon('search')}<input id="item-query" value="${esc(itemQ)}" placeholder="Search food, medicine or item" aria-label="Search an item"></div><div class="filters">${['Gundruk','Timur','Achar','Masala','Rice','Medicine','Wooden products','Traditional food'].map(x=>`<button class="chip ${itemQ===x?'active':''}" data-item="${x}">${x}</button>`).join('')}</div><div class="two-col"><section class="card"><span class="pill amber">Check with MPI · no permission decision</span><h2 style="margin-top:20px">${itemQ?esc(itemQ):'Know what’s in your bag'}</h2><p>${itemQ.toLowerCase().includes('medicine')?'Keep medicine in its original packaging and check medicine-specific import requirements with Medsafe and Customs. Carry supporting prescriptions where required.':itemQ.toLowerCase().includes('wood')?'Wood and plant-based products can pose biosecurity risks. Search the current MPI checker for the material and treatment requirements.':'Food, plant products, and animal products can have specific restrictions. Ingredients, processing, packaging, and country of origin matter.'}</p><h3>Declaration guidance</h3><p>${itemQ.toLowerCase().includes('medicine')?'Check the Customs declaration questions and the current medicine rules. Declare if required or if you are unsure.':'Declare food and relevant biosecurity-risk items on your arrival declaration. Do not assume dried, homemade, or commercially packed food is exempt.'}</p>${external(sources.mpi[1],'Open the current MPI item checker','btn')}${itemQ.toLowerCase().includes('medicine')?'<br>'+external('https://www.medsafe.govt.nz/consumers/miet/importmedicines.asp','Medsafe medicine guidance'):''}${source('mpi',true)}</section><aside class="stack">${section('Before you close your suitcase','<ul class="list"><li>Know the ingredients of your food.</li><li>Keep packaging and labels where possible.</li><li>Make items easy to show an officer.</li><li>Ask if you are unsure.</li></ul>')}${source('customs')}</aside></div>`}
function arrival(){const steps={'Before Flight':['Check passport, eVisa and travel documents','Confirm airline baggage allowance','Check transit entry requirements for your route','Prepare your New Zealand Traveller Declaration'],'During Flight':['Keep essential documents in hand luggage','Review your declaration answers','Ask cabin crew if you need assistance'],'Transit':['Follow airport transfer signs','Check whether bags are checked through','Check the next gate and local departure time','Follow the transit country’s entry requirements'],'Arrival':['Follow passport control signs','Collect your checked baggage','Declare and present biosecurity-risk items','Complete Customs and biosecurity checks','Meet your arranged transport']};return title('TRAVEL / FLIGHT & AIRPORT','From take-off to your first kia ora.','Your calm, practical guide through the airport.')+`<div class="filters">${Object.keys(steps).map(s=>`<button class="chip ${arrivalTab===s?'active':''}" data-arrival="${s}">${s}</button>`).join('')}</div><div class="two-col"><section class="card"><h2>${arrivalTab}</h2>${steps[arrivalTab].map((s,i)=>`<div class="level"><span class="level-number">${i+1}</span><div><h3>${s}</h3></div></div>`).join('')}${source('nztd')}</section><aside class="stack">${section('Your arrival airport','<p>International gateways include Auckland, Christchurch, Wellington, and Queenstown. Services depend on your itinerary.</p><span class="pill gray">No live flight data in prototype</span>')}${section('Ready for your first week?',`<p>SIM, transport, banking, and finding your feet.</p><button class="btn" data-action="arrived">I’ve arrived in New Zealand ${icon('arrow')}</button>`)}</aside></div>`}
function budget(){const b=state.budget;return title('MONEY / BUDGET PLANNER','Make room for your new life.','A realistic plan starts with your own numbers.')+notice('Illustrative amounts in NZD, not verified city averages. Excludes tuition, flights, insurance, visa fees, bond, and other one-off costs.')+`<div class="two-col"><section class="card"><div class="section-head"><h2>Your expenses</h2><div><button class="chip ${budgetPeriod==='Weekly'?'active':''}" data-period="Weekly">Weekly</button> <button class="chip ${budgetPeriod==='Monthly'?'active':''}" data-period="Monthly">Monthly</button></div></div>${Object.keys(b).filter(k=>k!=='Income').map(k=>`<label class="budget-input">${k}<span>$ <input type="number" min="0" max="100000" step="1" data-budget="${k}" aria-label="${k} ${budgetPeriod.toLowerCase()} NZD" value="${Math.round(b[k]*(budgetPeriod==='Monthly'?52/12:1))}"></span></label>`).join('')}<div class="divider"></div><label class="budget-input">Part-time income <span>$ <input type="number" min="0" max="100000" data-budget="Income" aria-label="Optional income" value="${Math.round(b.Income*(budgetPeriod==='Monthly'?52/12:1))}"></span></label><p class="micro">Optional · use take-home income you can realistically expect. Work rights depend on your visa.</p></section><aside class="stack budget-summary"><section class="journey-hero" id="budget-summary"></section>${source('study')}${link('jobs','Explore the job toolkit','btn secondary')}</aside></div>`}
function updateBudget(){let el=document.getElementById('budget-summary');if(!el)return;let total=Object.entries(state.budget).filter(([k])=>k!=='Income').reduce((a,[,v])=>a+Number(v),0),fmt=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD',maximumFractionDigits:0}).format(n);el.innerHTML=`<div class="eyebrow">YOUR PLAN AT A GLANCE</div><div class="big-number">${fmt(total)}</div><p>weekly expenses</p><div class="divider" style="background:#426b59"></div><p>Monthly <strong style="float:right;color:white">${fmt(total*52/12)}</strong></p><p>Annual living expenses <strong style="float:right;color:white">${fmt(total*52)}</strong></p><p>Weekly income balance <strong style="float:right;color:white">${fmt(state.budget.Income-total)}</strong></p><div class="divider" style="background:#426b59"></div><h3>A little breathing room</h3><p>Example emergency buffer: ${fmt(total*4)}<br>Four weeks of your expenses. Choose a buffer that fits your circumstances.</p><span class="micro" style="color:#c4d7c8">Monthly = weekly × 52 ÷ 12. This is a planning tool, not financial advice.</span>`}
const jobTools=['CV','LinkedIn','Cover letter','Interview preparation','References','Portfolio'];function jobs(){return title('WORK / JOB HUB','Your next opportunity starts here.','Build your confidence, one practical step at a time.')+`<div class="two-col"><div class="stack"><section class="journey-hero"><div class="eyebrow">YOUR JOB SEARCH TOOLKIT</div><h2>Show what you can do.</h2><p>You bring skills, experience, and a fresh perspective. Let’s help employers see them.</p><div class="progress-label"><span>${jobTools.filter(x=>state.checks['job:'+x]).length} of 6 ready</span></div><progress max="6" value="${jobTools.filter(x=>state.checks['job:'+x]).length}"></progress></section><section class="card"><h2>Get job-search ready</h2>${jobTools.map(x=>`<div class="task"><input type="checkbox" data-check="job:${x}" aria-label="Complete ${x}" ${state.checks['job:'+x]?'checked':''}><div class="task-content"><a class="task-title" href="#${x==='CV'?'cv':x==='Interview preparation'?'interview':'guide?topic='+encodeURIComponent(x)}">${x}</a><div class="task-meta">${x==='CV'?'Make your strengths easy to find':'Open your guide →'}</div></div>${icon('chevron')}</div>`).join('')}</section></div><aside class="stack">${section('Find opportunities',`<p>Browse external job websites. Listings are not aggregated here.</p><div class="rows">${[['https://www.sjs.co.nz/','Student Job Search'],['https://www.seek.co.nz/','SEEK'],['https://www.trademe.co.nz/a/jobs','Trade Me Jobs'],['https://www.careers.govt.nz/','Career guidance']].map(([u,n])=>external(u,n,'row-link')).join('')}</div>`)}${section('Know your rights',`<p>Understand your agreement, pay, breaks, and where to get help.</p>${link('rights','Employment rights','text-link')}`)}${section('Build your next skill',`<p>Turn “I should learn that” into a plan.</p>${link('skills','Open your skills roadmap','btn')}`)}</aside></div><div style="margin-top:24px">${categoryCards([['interview','users','Interview preparation','Practice clear answers and confident conversations.'],['guide?topic=Networking','users','Networking & workplace culture','Build connections and understand expectations.'],['guide?topic=Graduate jobs','briefcase','Graduate opportunities','Use your institution’s career team and employer events.']])}</div>`}
function cv(){return title('WORK / NZ CV GUIDE','Your experience has a story.','Make it clear, relevant, and easy to read.')+`<div class="filters">${['Skills-focused','Work-focused'].map(x=>`<button class="chip ${cvType===x?'active':''}" data-cv="${x}">${x} CV</button>`).join('')}</div><div class="two-col"><div class="stack"><div class="cv-paper"><span class="pill gray">Sample layout · page 1 of 2</span><h2 style="margin-top:22px">Aarav Sharma</h2><p>Christchurch · example@email.com · 021 000 0000<br>Portfolio: example.com · LinkedIn: sample profile</p><h3>Personal profile</h3><p>I am a software development student who enjoys building useful, accessible applications. I am seeking an entry-level opportunity where I can contribute my problem-solving skills and keep learning with an experienced team.</p>${cvType==='Skills-focused'?'<h3>Relevant skills</h3><p><strong>Software development</strong> — Built a responsive student event planner using JavaScript.<br><strong>Teamwork</strong> — Collaborated in a four-person student project.<br><strong>Communication</strong> — Presented designs and incorporated feedback.</p>':'<h3>Work & volunteer experience</h3><p><strong>Student volunteer · Sample community organisation</strong><br>2025–2026<br>Helped welcome attendees and coordinated event setup.</p>'}<h3>Education</h3><p><strong>Software development qualification</strong><br>Sample institution · Expected completion: 2027<br>Relevant topics: web development, databases, software testing.</p><h3>Projects</h3><p><strong>Campus event planner</strong><br>Built a responsive interface and tested the key user flows. Include a portfolio link and explain your own contribution.</p></div><div class="cv-paper"><span class="pill gray">Sample layout · page 2 of 2</span><h3>${cvType==='Skills-focused'?'Work & volunteer experience':'Relevant skills'}</h3><p>${cvType==='Skills-focused'?'Student volunteer · Sample community organisation<br>Helped coordinate events and welcome new students.':'JavaScript · HTML · CSS · Git<br>Use examples to demonstrate each relevant skill.'}</p><h3>Achievements</h3><p>Include genuine awards, recognition, or outcomes. Use numbers only when they are accurate.</p><h3>References</h3><p>Available on request. Ask permission before sharing anyone’s contact details.</p></div></div><aside class="stack">${section(cvType==='Skills-focused'?'Lead with transferable strengths':'Lead with relevant experience',`<p>${cvType==='Skills-focused'?'Useful when you have limited relevant work experience or are changing direction. Connect skills to real examples from study, work, volunteering, or projects.':'Useful when you have relevant employment history. Present recent experience clearly and describe the contribution you made.'}</p><ul class="list"><li>Tailor your CV to each role.</li><li>Use clear headings and readable type.</li><li>Keep the content honest and specific.</li><li>Proofread contact details and dates.</li></ul>${savedButton('cv','NZ CV guide','cv')}`)}${source('careers')}${link('interview','Next: prepare for interviews','btn')}</aside></div>`}
function interview(){return title('WORK / INTERVIEW PRACTICE','A good conversation starts with preparation.','Practise out loud, use real examples, and be yourself.')+`<div class="two-col"><div class="stack">${section('Use STAR to structure your story',`<div class="grid two">${[['S','Situation','Set the scene briefly.'],['T','Task','What were you responsible for?'],['A','Action','What did you actually do?'],['R','Result','What happened, and what did you learn?']].map(([s,h,p])=>`<div class="stat"><strong>${s}</strong><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>`)}${section('Common questions',`${['Tell me about yourself.','Why are you interested in this role?','Tell me about a challenge you solved.','How do you work in a team?','What would you like to learn?'].map(q=>`<details><summary>${q}</summary><p>Choose a genuine example. Keep it relevant to the role and explain your own contribution. Practise a concise answer, then invite follow-up questions.</p><label class="task"><input type="checkbox" data-check="practice:${q}" ${state.checks['practice:'+q]?'checked':''}>Practised this answer</label></details>`).join('')}<p class="micro">${Object.keys(state.checks).filter(k=>k.startsWith('practice:')&&state.checks[k]).length} of 5 questions practised</p>`)}</div><aside class="stack">${section('Questions you can ask','<ul class="list"><li>What does success look like in the first three months?</li><li>How does the team support learning?</li><li>What are the next steps in the process?</li></ul>')}${section('Before the interview','<ul class="list"><li>Research the organisation and role.</li><li>Prepare two or three examples.</li><li>Check the location or video link.</li><li>Bring questions and a copy of your CV.</li></ul>')}${section('NZ workplace communication','<p>Be respectful, clear, and curious. Ask for clarification when you need it. You do not need to hide your accent or pretend to know something you haven’t learned.</p>')}${source('careers')}</aside></div>`}
const skillGroups={'Must have':['HTML','CSS','JavaScript','Git/GitHub','Programming fundamentals','Communication','Basic testing'],'Should have':['React','TypeScript','REST APIs','SQL','Portfolio projects','LinkedIn','Interview preparation'],'Could have':['Cloud','Docker','CI/CD','Next.js','AI-assisted development','Open-source contributions']};function skills(){let all=Object.values(skillGroups).flat(),conf=all.filter(x=>state.skills[x]==='Confident').length,learning=all.filter(x=>state.skills[x]==='Learning').length;return title('WORK / SKILLS ROADMAP','Small skills. Bigger possibilities.','Your example roadmap to junior software development.')+`<section class="journey-hero" style="margin-bottom:24px"><div class="hero-flex"><div><div class="eyebrow">JUNIOR SOFTWARE DEVELOPER</div><h2>${conf} skills feeling confident</h2><p>${learning} in progress · ${all.length-conf-learning} still to explore</p></div><span class="icon-tile" style="width:65px;height:65px">${icon('code')}</span></div><progress max="${all.length}" value="${conf}"></progress><p class="micro" style="margin-top:10px">Self-assessed readiness: ${Math.round(conf/all.length*100)}% · a learning guide, not an employment prediction.</p></section><div class="grid">${Object.entries(skillGroups).map(([g,ss],j)=>`<section class="card"><span class="pill ${j===1?'blue':j===2?'amber':''}">${g.toUpperCase()}</span><p style="font-size:13px;margin-top:12px">${['Build a strong foundation.','Stand out with practical evidence.','Explore as your goals develop.'][j]}</p>${ss.map(s=>`<label class="skill-row"><span>${s}</span><select data-skill="${s}" aria-label="${s} confidence">${['Not started','Learning','Confident'].map(o=>`<option ${(state.skills[s]||'Not started')===o?'selected':''}>${o}</option>`).join('')}</select></label>`).join('')}</section>`).join('')}</div><div style="margin-top:22px">${notice('This illustrative roadmap does not guarantee employment. Requirements vary by employer and role; use real job descriptions and feedback to adapt your plan.',true)}</div>`}
const organisations=[{id:'canterbury',name:'Nepal New Zealand Friendship Society of Canterbury',city:'Christchurch',cat:'Community organisations',desc:'A place to start looking for Nepalese community connections in Canterbury.'},{id:'nrna',name:'NRNA New Zealand',city:'National',cat:'Professional networks',desc:'Connect with wider Nepalese networks across Aotearoa.'},{id:'society',name:'New Zealand Nepal Society',city:'Auckland',cat:'Cultural groups',desc:'Explore cultural connections and community activities.'},{id:'student',name:'Campus Nepali Student Circle',city:'Christchurch',cat:'Student associations',desc:'Illustrative student group for campus meet-ups and shared support.'},{id:'grocery',name:'Neighbourhood Nepali Grocer',city:'Christchurch',cat:'Groceries',desc:'Illustrative business listing. Discover familiar ingredients nearby.'},{id:'sports',name:'Weekend Football Together',city:'Christchurch',cat:'Sports',desc:'Illustrative informal student sports group.'},{id:'restaurant',name:'Himalayan Table',city:'Christchurch',cat:'Restaurants',desc:'Illustrative restaurant listing.'},{id:'religious',name:'Community Gathering Space',city:'Christchurch',cat:'Religious/community services',desc:'Illustrative community service listing.'}];function orgCard(o){return `<article class="card category"><div class="section-head"><span class="icon-tile">${icon('users')}</span>${savedButton('org:'+o.id,o.name,'organisation?id='+o.id)}</div><span class="pill gray">Community listing · not verified</span><h3>${o.name}</h3><p>${o.desc}</p><span class="micro">${o.city} · ${o.cat}</span>${link('organisation?id='+o.id,'Meet the organisation','text-link')}</article>`}function community(){const list=organisations.filter(o=>(communityCategory==='All'||o.cat===communityCategory||communityCategory==='Nepali businesses'&&['Groceries','Restaurants'].includes(o.cat))&&(communityCity==='All cities'||o.city===communityCity||o.city==='National'));return title('COMMUNITY',t('New place. Familiar faces.','नयाँ ठाउँ। आफ्नोपनको साथ।'),t('Find your people, share a little home, and make new connections.','आफ्नो समुदायसँग जोडिनुहोस् र नयाँ साथी बनाउनुहोस्।'))+`<div class="section-head"><label>${icon('pin')} <select id="community-city" aria-label="Community city">${['All cities','Christchurch','Auckland','Wellington','Hamilton','Dunedin'].map(c=>`<option ${communityCity===c?'selected':''}>${c}</option>`).join('')}</select></label><div><button class="chip ${!mapMode?'active':''}" data-action="listmode">List</button> <button class="chip ${mapMode?'active':''}" data-action="mapmode">Map</button></div></div><div class="filters">${['All','Community organisations','Student associations','Cultural groups','Sports','Religious/community services','Nepali businesses','Restaurants','Groceries','Professional networks'].map(x=>`<button class="chip ${communityCategory===x?'active':''}" data-community="${x}">${x}</button>`).join('')}${link('events','Events','chip','calendar')}</div>${mapMode?`<div class="notice">${icon('pin')}Map preview uses illustrative positions, not real addresses or directions.</div><div class="map-panel">${list.map(o=>`<a href="#organisation?id=${o.id}" class="map-pin">${icon('pin')}<strong>${o.name}</strong><br><small>${o.city}</small></a>`).join('')||'<p>No sample listings in this area.</p>'}</div>`:list.length?`<div class="grid">${list.map(orgCard).join('')}</div>`:empty('No listings in this view yet','Try another category or choose All cities.','community','Browse community')}<div style="margin-top:25px">${notice('Community listings are not official advice or endorsements. Organisation names are starting points for research; contact details and activities still need verification.')}</div>`}
function organisation(){let o=organisations.find(o=>o.id===params.get('id'))||organisations[0];return link('community','Back to your community','back','back')+title('COMMUNITY / ORGANISATION',o.name,o.city+' · '+o.cat,savedButton('org:'+o.id,o.name,'organisation?id='+o.id))+`<div class="two-col"><div class="stack">${section('A connection closer to home',`<span class="pill gray">Community listing · verification pending</span><p style="margin-top:20px">${o.desc}</p><p>Before attending or sharing personal details, independently confirm the organiser, location, cost, and event information.</p>`)}${section('Ways to get involved','<ul class="list"><li>Ask about upcoming community gatherings.</li><li>Look for student or volunteer opportunities.</li><li>Connect with people who share your interests.</li></ul>'+link('events','Explore sample events','btn'))}</div><aside>${section('Contact information','<p>Official contact details have not been verified for this prototype.</p><span class="pill amber">Needs review</span><p class="micro" style="margin-top:15px">Last verified: not yet reviewed</p>')}</aside></div>`}
function events(){return title('COMMUNITY / EVENTS','Make a little room for belonging.','Culture, connection, and something to look forward to.')+notice('All events below are fictional sample data. Dates, hosts, and locations are not confirmed.')+`<div class="grid">${[['dashain','17','OCT','Dashain Celebration','Community organisation','Christchurch'],['meetup','24','OCT','New student chai & chat','Sample student circle','Christchurch'],['career','06','NOV','Your first NZ career connection','Sample professional network','Auckland']].map(([id,d,m,h,host,c])=>`<article class="card"><div class="section-head"><div class="event-date"><span>${m}</span><strong>${d}</strong></div>${savedButton('event:'+id,h,'events')}</div><span class="pill gray">Sample event · 2026</span><h3 style="margin-top:15px">${h}</h3><p>${c}<br>Hosted by ${host}</p><div class="inline-actions"><button class="btn secondary small" data-reminder="${id}" data-title="${h}">${state.saved.some(x=>x.id==='reminder:'+id)?'✓ Reminder saved':'Add reminder'}</button>${link('organisation?id=canterbury','View organisation','text-link')}</div><p class="micro" style="margin-top:14px">Reminders appear in Journey; no push notification is sent.</p></article>`).join('')}</div>`}
const housingItems={'Student accommodation':'Check the provider’s accommodation options, costs, included services, support, and cancellation terms before committing.','Homestay':'Ask what meals, transport, internet, and household expectations are included. Confirm who manages student support.','Flatting':'Talk about bills, chores, guests, and notice before moving in. Put your agreement in writing.','Renting':'Read the agreement, inspect the property, and understand the total move-in cost.','Tenant vs flatmate':'Your legal position can differ depending on whose name is on the tenancy agreement. Check the relevant guidance before signing.','Bond':'Check how a tenancy bond should be handled, recorded, and lodged. Keep receipts and written confirmation.','Rent in advance':'Check current rules and the written agreement before paying.','Utilities':'Ask which bills are included and how shared costs are divided.','Moving checklist':'Record condition with photos, test keys, confirm the move-in date, and keep signed paperwork.','Avoiding scams':'Verify the property and the person renting it. Be cautious about pressure to pay before you can inspect or confirm the arrangement.','Tenancy problems':'Keep written records and use Tenancy Services to understand your options.'};
function housing(){return title('LIVING / HOUSING','A place to feel settled.','Understand your options before you sign or pay.')+`<div class="two-col"><section>${Object.entries(housingItems).map(([h,p])=>`<details><summary>${h}</summary><p>${p}</p>${external(sources.tenancy[1],'Check Tenancy Services')}</details>`).join('')}</section><aside class="stack">${section('Before you move in','<ul class="list"><li>Check the address and agreement.</li><li>Understand who pays each bill.</li><li>Keep records of all payments.</li><li>Know who to contact for repairs.</li></ul>'+link('budget','Plan your housing budget','btn'))}${source('tenancy')}</aside></div>`}
function rights(){const items={'Employment agreement':'Read your written agreement and ask about anything you do not understand before signing.','Minimum wage':'Check the current rate and whether any specific categories apply. Do not rely on an old amount.','Payslips':'Keep records of hours worked and payments received. Ask how your employer records and explains your pay.','Holiday pay':'Check the official guidance for your employment type and circumstances.','Breaks':'Understand your current rest and meal break entitlements.','Migrant worker rights':'Learn about your employment rights and the conditions on your visa.','Workplace exploitation':'Keep evidence and contact the official migrant exploitation support channel.','Where to get help':'Employment New Zealand provides official information and routes to support.'};return title('WORK / YOUR RIGHTS','Fair work is everyone’s right.','Know what to check. Know where to get help.')+notice('<strong>Never pay someone to obtain a job.</strong> Be cautious of anyone selling job offers or demanding recruitment payments.')+`<div class="two-col"><section>${Object.entries(items).map(([h,p])=>`<details><summary>${h}</summary><p>${p}</p>${external(sources.employment[1],'Read current official guidance')}</details>`).join('')}</section><aside>${source('employment')}${link('support','Get support','btn')}</aside></div>`}
function consular(){return title('SERVICES / NEPAL','A connection to home, when you need it.','Passport, documents, and official Nepalese consular guidance.')+notice('Confirm current procedures, jurisdiction, appointments, fees, and contact details directly with the Embassy. This prototype does not publish unverified fees.')+`<div class="two-col"><section class="card"><h2>What do you need help with?</h2>${['Passport renewal','Lost passport','Travel documents','Document services','Embassy contacts','Consular services in New Zealand','Emergency contacts'].map(h=>`<details><summary>${h}</summary><p>Start with the Embassy of Nepal in Canberra’s current instructions. Ask which authorised office or representative handles your request in New Zealand.</p>${external(sources.nepal[1],'Open Embassy guidance')}</details>`).join('')}</section><aside class="stack">${section('Embassy of Nepal, Canberra','<p>Use the official embassy website to verify available services and the current list of representatives in New Zealand. Do not rely on community reposts of fees or contact details.</p>'+source('nepal')+'<div class="divider"></div>'+external('https://nepalconsulate.nz/consular-services/e-passport/','Consulate of Nepal, Auckland')+'<p class="micro">Confirm current service scope with the Embassy before arranging travel.</p>')}${section('Immediate danger in NZ',`<a class="help-number" href="tel:111">111</a><p>Police, fire, or ambulance emergencies.</p>`)}</aside></div>`}
function travel(){return title('LIVING / TRAVEL & TRANSPORT','Find your way, safely.','From your first bus ride to your first road trip.')+`<div class="grid">${[['Public transport','Check your city’s official transport site for fares, routes, payment methods, and student concessions.'],['Driving in New Zealand','Learn local road rules and conditions before driving. Plan rest stops and drive to conditions.'],['Overseas driver licences','Rules depend on your licence, vehicle type, and circumstances. Check the current NZTA guidance before you drive.'],['Buying a car','Check vehicle history, inspection requirements, ongoing costs, and change-of-ownership processes.'],['Car insurance','Compare cover, exclusions, excess, and driver requirements with the insurer.'],['Road rules','Study the current official Road Code and understand intersections and speed limits.'],['Cycling','Use safe equipment, learn local cycling rules, and choose routes that match your confidence.'],['Domestic travel','Plan time, weather, accessibility, and cancellation options.'],['Road trips','Allow more time than map distances suggest. Check road conditions and weather.']].map(([h,p])=>`<article class="card"><span class="icon-tile">${icon(h==='Cycling'?'compass':'car')}</span><h3 style="margin-top:15px">${h}</h3><p style="font-size:14px">${p}</p>${h==='Overseas driver licences'?'<span class="pill amber">Effective date: check current official rule</span>':''}${external(h==='Public transport'?'https://www.metroinfo.co.nz/':sources.nzta[1],h==='Public transport'?'Christchurch Metro':'Check NZTA guidance')}</article>`).join('')}</div>${source('nzta')}`}
function support(){return title('HELP / STUDENT SUPPORT','You don’t have to figure it out alone.','Practical support for study, wellbeing, and life in New Zealand.')+`<section class="card" style="border-color:#d2a7a0;margin-bottom:24px"><div class="section-head"><div><span class="pill red">Immediate danger or emergency</span><h2 style="margin-top:14px">Police, fire, or ambulance</h2></div><a href="tel:111" class="btn danger" style="font-size:24px">Call 111</a></div><p style="margin:0">If you need urgent emergency help in New Zealand, call 111.</p></section><div class="grid">${[['Code of Pastoral Care','Learn about the responsibilities of education providers and support for learners.','https://www2.nzqa.govt.nz/tertiary/the-code/'],['Academic problems & provider support','Start with your tutor, programme leader, learning support, or international student team.','https://www.studywithnewzealand.govt.nz/'],['Complaints','Follow your provider’s complaints process and check NZQA guidance for next steps.','https://www2.nzqa.govt.nz/'],['Employment problems','Get official information about fair treatment and employment disputes.',sources.employment[1]],['Housing problems','Check the right support route for your tenancy or flatting situation.',sources.tenancy[1]],['Financial difficulty','Contact your student support team early and ask what assistance may be available.','https://www.studywithnewzealand.govt.nz/'],['Wellbeing','Find current mental wellbeing and counselling support options.','https://1737.org.nz/'],['Non-emergency police help','For matters that do not require an emergency response.','https://www.police.govt.nz/105support']].map(([h,p,u])=>`<article class="card"><span class="icon-tile">${icon('heart')}</span><h3 style="margin-top:15px">${h}</h3><p style="font-size:14px">${p}</p>${external(u,'Find support')}</article>`).join('')}</div>`}
function journey(){let data=checklistData();return title('YOUR JOURNEY','One step at a time.','A plan that grows with you.',link('profile','Change stage','btn secondary'))+`<div class="journey-track">${['Exploring study','Preparing to travel','First weeks in NZ','Studying','Near graduation'].map(x=>`<span class="${x===state.stage?'active':''}" title="${x}"></span>`).join('')}</div><div class="two-col"><div class="stack"><section class="card"><span class="pill">${state.stage}</span><h2 style="margin-top:18px">Your current checklist</h2>${Object.entries(data).flatMap(([g,ls])=>ls.map(n=>checkTask(n,g))).join('')}</section>${section('Checklist history',`<p>${Object.values(state.checks).filter(Boolean).length} completed tasks across your journey.</p>${Object.entries(state.checks).filter(([,v])=>v).slice(-8).map(([k])=>`<div class="row-link"><span>${icon('check')}${esc(k.split(':').slice(1).join(':'))}</span><span class="pill">Complete</span></div>`).join('')||'<p class="micro">Your completed steps will appear here.</p>'}`)}</div><aside class="stack">${section('Your checklists',`<div class="rows">${link('predeparture','Pre-departure checklist','row-link')}${link('firstweek','First-week checklist','row-link')}${link('jobs','Job search toolkit','row-link')}${link('saved','Saved resources','row-link')}</div>`)}${section('Upcoming reminders',state.saved.filter(x=>x.id.startsWith('reminder:')).map(x=>`<a class="row-link" href="#events">${esc(x.title)}</a>`).join('')||'<p>No reminders yet. Save a sample event reminder to keep it here.</p>')}</aside></div>`}
function empty(h,p,r,label){return `<div class="empty"><span class="icon-tile">${icon('save')}</span><h2>${h}</h2><p>${p}</p>${link(r,label)}</div>`}
function saved(){return title('JOURNEY / SAVED','Good finds, all together.','Your courses, guides, connections, and plans.')+(state.saved.length?`<div class="grid two">${state.saved.map(x=>`<article class="card"><div class="section-head"><span class="pill gray">${esc(x.id.split(':')[0])}</span>${savedButton(x.id,x.title,x.target)}</div><h3>${esc(x.title)}</h3>${link(x.target,'Open resource','text-link')}</article>`).join('')}</div>`:empty('Your saved space is waiting','Tap a bookmark on any course, guide, organisation, or event.','explore','Find something useful'))}
const searchItems=[...categories.map(([r,i,h,p])=>({r,h,p,g:['courses','education'].includes(r)?'Study':r==='community'?'Community':r==='jobs'?'Jobs':['consular','support'].includes(r)?'Services':'Guides'})),{r:'visa?topic=Working while studying',h:'Work hours & student visa conditions',p:'Check the conditions on your visa with INZ.',g:'Guides'},{r:'consular',h:'Passport renewal',p:'Nepal Embassy in Canberra and consular services.',g:'Services'},{r:'housing',h:'Accommodation in Christchurch',p:'Flatting, rent, and housing costs.',g:'Guides'},{r:'cv',h:'How to write a NZ CV',p:'Skills-focused and work-focused CV layouts.',g:'Jobs'},{r:'bring',h:'Bring achar and food to New Zealand',p:'Check MPI and declare biosecurity-risk items.',g:'Guides'},{r:'courses',h:'Software engineering courses',p:'Find and compare study options.',g:'Study'},{r:'community',h:'Nepali community in Auckland',p:'Find community organisations and connections.',g:'Community'},...courses.map(c=>({r:'course?id='+c.id,h:c.name,p:c.provider+' '+c.city,g:'Study'}))];
function search(){let words=globalQ.toLowerCase().split(/\s+/).filter(x=>x.length>2),list=globalQ?searchItems.filter(x=>words.some(w=>(x.h+' '+x.p).toLowerCase().includes(w))):searchItems.slice(0,6);return title('GLOBAL SEARCH','What’s on your mind?','Find the right starting point across Sajilo NZ.')+`<div class="searchbox">${icon('search')}<input id="global-query" placeholder="Search guides, courses, community and more" value="${esc(globalQ)}" aria-label="Search all resources"></div><div class="filters">${['work hours student visa','passport renewal','cheap accommodation Christchurch','how to write NZ CV','bring achar to New Zealand','software engineering courses','Nepali community Auckland'].map(x=>`<button class="chip" data-query="${x}">${x}</button>`).join('')}</div>${list.length?['Guides','Study','Community','Jobs','Services'].map(g=>{let items=list.filter(x=>x.g===g);return items.length?`<section style="margin:25px 0"><h2>${g}</h2><div class="rows">${items.map(x=>`<a class="row-link" href="#${x.r}"><div><strong>${x.h}</strong><small>${x.p}</small></div>${icon('chevron')}</a>`).join('')}</div></section>`:''}).join(''):empty('No results yet','Try fewer words or explore a category.','explore','Browse categories')}`}
function profile(){return title('YOUR SPACE',t('Make Sajilo NZ feel like you.','सजिलो NZ लाई आफ्नो बनाउनुहोस्।'),t('Your journey changes. Your companion changes with it.','तपाईंको यात्रासँगै तपाईंको साथी पनि बदलिन्छ।'))+`<div class="two-col"><section class="card"><h2>My journey</h2>${onboarding.filter((_,i)=>i<5).map(([h,p,k,opts])=>`<label style="display:block;margin:20px 0"><span style="display:block;margin-bottom:8px;font-size:14px">${h}</span><select data-profile="${k}" style="width:100%">${opts.map(o=>`<option ${state[k]===o?'selected':''}>${o}</option>`).join('')}</select></label>`).join('')}<p class="micro">Changes save automatically on this device.</p>${link('home','See my updated dashboard')}</section><aside class="stack">${section('Your data & privacy','<p>This frontend prototype stores your preferences, saved resources, budget, and progress in this browser. No account or backend is connected.</p><button class="btn secondary" data-action="reset">Reset this device’s prototype data</button>')}${section('Explore the prototype',`<div class="rows">${link('welcome','Welcome screen','row-link')}${link('onboarding','Try onboarding again','row-link')}${link('design','Design system & screen index','row-link')}</div>`)}${section('Language',`<p>English and selected नेपाली screens are available. Untranslated guides currently fall back to English.</p><button class="btn secondary" data-action="language">EN | नेपाली</button>`)}</aside></div>`}
const guideCopy={'About New Zealand':['Welcome to Aotearoa','Get to know the country, its regions, people, and everyday life. Start with official study and visitor information.'],'Culture & Māori culture':['Learn with respect','Māori are tangata whenua of Aotearoa. Learn pronunciation, local place names, and tikanga from trusted Māori-led resources and your institution.'],'Weather & climate':['Plan for changing weather','Weather differs by region and can change quickly. Check forecasts, dress in layers, and prepare before heading outdoors.'],'Healthcare':['Find the right care','Ask your institution about healthcare access, insurance, and nearby providers. Confirm costs and cover before a non-urgent appointment.'],'Laws & everyday rules':['Learn the everyday essentials','Use official sources for laws and rules. Your institution can help explain who to contact when something is unclear.'],'Student life':['Build a routine that works for you','Attend orientation, meet your tutors, explore clubs, and ask about academic support early.'],'Cover letter':['Connect your strengths to the role','Use a clear opening, two or three relevant examples, and a short closing. Explain why this role interests you and what you can contribute.'],'References':['Ask before you share','Choose someone who can speak honestly about your work, study, or volunteering. Ask their permission and explain the role you are applying for.'],'Portfolio':['Show your contribution','Choose a few strong projects. Explain the problem, your role, decisions, and what you learned. Include accessible demos or clear screenshots.'],'LinkedIn':['Make your skills easy to find','Use an accurate headline, concise summary, projects, and education. Connect thoughtfully with classmates, lecturers, and people you meet.'],'Networking':['Start with a conversation','Attend campus events and local meet-ups. Ask curious questions, follow up respectfully, and offer help when you can.'],'Graduate jobs':['Look ahead, one step at a time','Ask your institution’s careers team about employer events and graduate recruitment timelines. Tailor each application and check visa conditions separately.']};Object.assign(guideCopy,{'Get a SIM':['Stay connected','Compare prepaid plans, coverage, data allowance, and phone compatibility. Ask your student support team where to buy a SIM or eSIM safely.'],'Open a bank account':['Prepare before visiting a bank','Check the bank’s own identity, address, and student account requirements. Confirm whether you can begin the process before arrival. Do not share passwords or PINs.'],'Apply for an IRD number':['Use the official Inland Revenue process','Check the application process that matches your situation on Inland Revenue’s website. Prepare the identity and address evidence requested there. Do not pay an unofficial intermediary.'],'Register with a healthcare provider':['Get care organised early','Check your insurance, eligibility, and local provider fees. Your institution’s international team can help you find a suitable healthcare provider.'],'Passport':['Keep your identity document safe','Check passport validity against your travel and visa requirements. Keep a secure copy and carry the original where required.'],'Medication':['Check before you pack','Use current Medsafe and Customs guidance. Keep medicines identifiable and check whether a prescription or other evidence is needed.'],'Transit requirements':['Check every country on your itinerary','Ask your airline and check official transit-country requirements for your passport and route. Rules can differ when collecting baggage or changing airports.']});function guide(){let topic=params.get('topic')||'Student life',[h,p]=guideCopy[topic]||['Take the next practical step','Use trusted sources and your institution’s support team to get current guidance.'];return title('POCKET GUIDE',esc(topic),'A short guide for your next step.',savedButton('guide:'+topic,topic,'guide?topic='+encodeURIComponent(topic)))+`<div class="two-col"><section class="card"><h2>${h}</h2><p>${p}</p><h3>Make it manageable</h3><ul class="list"><li>Choose one action you can do today.</li><li>Save the relevant official information.</li><li>Ask your student support team if you need help.</li></ul>${topic==='Apply for an IRD number'?external('https://www.ird.govt.nz/managing-my-tax/ird-numbers','Inland Revenue: IRD numbers','btn'):''}${source(['Cover letter','References','Portfolio','LinkedIn','Networking','Graduate jobs'].includes(topic)?'careers':'study')}</section><aside>${section('Keep going',link('explore','Explore more guides','text-link')+'<br>'+link('journey','Return to my journey','text-link'))}</aside></div>`}
const screenIndex=[['welcome','Welcome / landing'],['onboarding','Onboarding'],['home','Personalised dashboard'],['explore','Explore New Zealand'],['city','City page'],['education','Education system'],['courses','Course search'],['course','Course details'],['compare','Compare courses'],['immigration','Immigration hub'],['update','Immigration update details'],['predeparture','Pre-departure checklist'],['bring','Can I bring it?'],['arrival','Arrival guide'],['firstweek','First-week checklist'],['housing','Housing'],['budget','Student budget calculator'],['jobs','Job hub'],['cv','CV guide'],['interview','Interview guide'],['skills','Skills roadmap'],['community','Community directory'],['organisation','Community organisation'],['events','Events'],['consular','Consular services'],['travel','Travel & driving'],['support','Student support'],['search','Global search'],['saved','Saved journey'],['profile','Profile / settings'],['institution','Institution'],['rights','Employment rights']];
function design(){return title('PROTOTYPE / DESIGN SYSTEM','A companion, built around the journey.','Screen index, information architecture, reusable patterns, and validation plan.')+`<div class="stack">${section('The product structure',`<div class="grid">${[['Home','Personalised next steps · updates · quick tools'],['Explore','Study · immigration · travel · housing · money · work · support'],['Journey','Stage-specific checklists · history · saved resources · reminders'],['Community','Directory · organisation profiles · events'],['Profile','Journey preferences · language · local data controls']].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div><p class="micro">Mobile: five-item fixed bottom navigation. Desktop: persistent left navigation, search in the header, two-column workspaces, and wide comparison tables.</p>`)}${section('All prototype screens',`<div class="grid">${screenIndex.map(([r,n],i)=>`<a class="row-link" href="#${r}"><span><small>${String(i+1).padStart(2,'0')}</small>${n}</span>${icon('chevron')}</a>`).join('')}</div>`)}${section('Visual foundations',`<div class="swatches"><div class="swatch" style="background:#174f40">Forest<br>#174F40</div><div class="swatch" style="background:#bc4639">Nepal red<br>#BC4639</div><div class="swatch" style="background:#213b34">Ink<br>#213B34</div><div class="swatch" style="background:#e9f1eb;color:#213b34">Mint<br>#E9F1EB</div><div class="swatch" style="background:#f7f8f4;color:#213b34;border:1px solid #ccc">Canvas<br>#F7F8F4</div></div><p style="margin-top:22px">Manrope headings · DM Sans body · Noto Sans Devanagari fallback. 16px base text. 8px spacing rhythm. 12–18px card radii. High-contrast focus rings. Responsive layouts at 700px, 900px, and 1150px.</p><p class="micro">Buttons target at least 44px where practical. Compact secondary controls need final touch-target and WCAG 2.2 AA audit before production.</p>`)}${section('Source & verification components',`<div class="inline-actions"><span class="pill">Verified</span><span class="pill blue">Updated</span><span class="pill amber">Upcoming change</span><span class="pill red">Needs review</span><span class="pill gray">Community information</span><span class="pill">Verified organisation · component example</span></div>${source('inz',true,'16 November 2026',updateUrl)}<p class="micro" style="margin-top:12px">A verified organisation badge requires documented identity and official-contact checks. No community listing is assigned that status in this prototype. Dates are attached to individual content, not inferred from the current date.</p>`)}${section('Empty, loading, and error states',`<div class="grid"><div class="empty"><h3>Nothing saved yet</h3><p>Bookmark something useful.</p>${link('explore','Explore','btn small')}</div><div aria-label="Loading example"><h3>Finding your next step…</h3><div class="skeleton"></div><div class="skeleton"></div></div><div class="notice" style="display:block"><h3>We couldn’t load this update.</h3><p>Your saved progress is still here.</p><button class="btn secondary" data-action="retry">Try again</button></div></div>`)}${section('User journeys',`<div class="rows">${[['Prospective student','Welcome → language → location → study stage → city → course finder → course → save → framework → student visa → add travel checklist'],['Pre-departure student','Change stage → dashboard → documents and packing → MPI item checker → arrival guide'],['Newly arrived student','I’ve arrived → first-week checklist → budget → job hub → CV → local community'],['Current student / graduate','Job toolkit → interview practice → skills roadmap → official post-study update → licensed advice if needed']].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div>`)}${section('Validate before building a backend','<p>These are design hypotheses, not findings from user interviews. Test with Nepal-based students, recent arrivals, current students, and graduates, including Nepali-language users.</p><ol class="list"><li>Find and save a software-development course in Christchurch.</li><li>Explain whether an immigration card determines personal eligibility.</li><li>Change stage and find the matching checklist.</li><li>Look up achar and explain the next official action.</li><li>Adjust the budget and explain monthly conversion.</li><li>Find CV guidance and mark a skill as Learning.</li><li>Distinguish a community listing from a verified organisation.</li></ol><p>Observe completion, wrong turns, confidence, reading difficulty, keyboard access, and mobile reach. Review translation with a native Nepali reviewer and source wording with appropriate domain experts.</p>')}${section('Frontend architecture & scope','<p>Reusable page shell, cards, source panels, checklists, filters, course cards, status badges, and empty states. Profile, bookmarks, checklist progress, skills, and budget use a device-local store.</p><p>Translation is selected through a shared language helper; English is the fallback. Before full localisation, move all copy into versioned locale dictionaries, add translation review, and localise date/number formatting.</p><p>This is a PWA-style responsive UX prototype. No backend, authentication, push notifications, live jobs, flight feeds, verified provider catalogue, service-worker offline mode, or production installation flow has been developed. The technical backlog and sprint plan follow design approval.</p>')}</div>`}
function render(scroll=true){let [r,q]=location.hash.slice(1).split('?');route=r||'home';params=new URLSearchParams(q||'');const pages={welcome,onboarding:onboard,home,explore,city,education,courses:coursesPage,course:courseDetail,institution,compare:comparePage,immigration,update,visa,predeparture:()=>checklist('predeparture'),firstweek:()=>checklist('firstweek'),bring,arrival,budget,jobs,cv,interview,skills,community,organisation,events,housing,rights,consular,travel,support,journey,saved,search,profile,guide,design};document.documentElement.lang=state.lang==='EN'?'en':'ne';document.getElementById('app').innerHTML=shell((pages[route]||(()=>empty('This page isn’t here','Head back to your journey and choose another path.','home','Go home')))());document.title=(screenIndex.find(([r])=>r===route)?.[1]||'Your companion')+' · Sajilo NZ';updateBudget();if(scroll)window.scrollTo(0,0)}
window.addEventListener('hashchange',()=>render());document.addEventListener('click',e=>{const b=e.target.closest('[data-action],[data-option],[data-save],[data-compare],[data-imm],[data-item],[data-arrival],[data-period],[data-cv],[data-community],[data-query],[data-reminder]');if(!b)return;if(b.dataset.save){save(b.dataset.save,b.dataset.title,b.dataset.target);return}if(b.dataset.option){let k=onboarding[onstep][2],v=b.dataset.option;if(k==='interests')state.interests=state.interests.includes(v)?state.interests.filter(x=>x!==v):[...state.interests,v];else state[k]=v;persist();render(false);return}if(b.dataset.compare){let id=b.dataset.compare;if(compare.includes(id))compare=compare.filter(x=>x!==id);else if(compare.length<3)compare.push(id);else{toast('Compare up to three courses at a time.');return}render(false);toast(compare.includes(id)?'Added to comparison':'Removed from comparison');return}if(b.dataset.imm){immFilter=b.dataset.imm;render(false)}if(b.dataset.item){itemQ=b.dataset.item;render(false)}if(b.dataset.arrival){arrivalTab=b.dataset.arrival;render(false)}if(b.dataset.period){budgetPeriod=b.dataset.period;render(false)}if(b.dataset.cv){cvType=b.dataset.cv;render(false)}if(b.dataset.community){communityCategory=b.dataset.community;render(false)}if(b.dataset.query){globalQ=b.dataset.query;render(false)}if(b.dataset.reminder){save('reminder:'+b.dataset.reminder,b.dataset.title,'events');return}switch(b.dataset.action){case 'language':state.lang=state.lang==='EN'?'नेपाली':'EN';persist();render(false);break;case 'onnext':case 'onskip':if(b.dataset.action==='onskip'){let k=onboarding[onstep][2];state[k]=k==='interests'?[]:'Not decided'}if(onstep<5){onstep++;render()}else{state.onboarded=true;persist();go('home');toast('Your journey is ready. Namaste!')}break;case 'onback':if(onstep){onstep--;render()}break;case 'addcheck':state.saved=state.saved.filter(x=>x.id!=='checklist:pre');state.saved.push({id:'checklist:pre',title:'Pre-departure checklist',target:'predeparture'});persist();toast('Pre-departure checklist added to Journey');break;case 'arrived':state.location='Recently arrived';state.stage='First weeks in NZ';persist();go('firstweek');toast('Welcome to New Zealand! Your checklist is ready.');break;case 'clearfilters':courseQuery='';courseCity='All cities';courseLevel='All levels';courseSubject='All subjects';courseProvider='All institutions';courseDuration='Any duration';courseIntake='Any intake';render(false);break;case 'listmode':mapMode=false;render(false);break;case 'mapmode':mapMode=true;render(false);break;case 'reset':if(confirm('Reset all saved progress and preferences on this device?')){localStorage.removeItem('sajilo-prototype');state=JSON.parse(JSON.stringify(initial));onstep=0;go('welcome');toast('Prototype data reset')}break;case 'retry':b.closest('.notice').innerHTML='<h3>Ready to explore</h3><p>Connection restored. This demonstrates the recovery state.</p>';break}});
document.addEventListener('change',e=>{let el=e.target;if(el.dataset.check){state.checks[el.dataset.check]=el.checked;persist();render(false)}if(el.dataset.skill){state.skills[el.dataset.skill]=el.value;persist();render(false)}if(el.dataset.profile){state[el.dataset.profile]=el.value;if(el.dataset.profile==='location'&&el.value==='Recently arrived')state.stage='First weeks in NZ';persist();render(false);toast('Your journey preferences are saved')}const setters={'filter-city':v=>courseCity=v,'filter-level':v=>courseLevel=v,'filter-duration':v=>courseDuration=v,'filter-intake':v=>courseIntake=v,'filter-subject':v=>courseSubject=v,'filter-provider':v=>courseProvider=v,'community-city':v=>communityCity=v};if(setters[el.id]){setters[el.id](el.value);render(false)}});
let inputTimer;document.addEventListener('input',e=>{const el=e.target;if(el.dataset.budget){state.budget[el.dataset.budget]=Math.max(0,Number(el.value)||0)/(budgetPeriod==='Monthly'?52/12:1);persist();updateBudget();return}if(['course-query','global-query','item-query'].includes(el.id)){const id=el.id,pos=el.selectionStart,v=el.value;if(id==='course-query')courseQuery=v;if(id==='global-query')globalQ=v;if(id==='item-query')itemQ=v;clearTimeout(inputTimer);inputTimer=setTimeout(()=>{render(false);let next=document.getElementById(id);next.focus();next.setSelectionRange(pos,pos)},260)}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();go('search');setTimeout(()=>document.getElementById('global-query')?.focus(),50)}});render();
